/bin/bash -c "find . -maxdepth 2 -type f -printf '%p %s bytes\\n' | sort | sed -n '1,200p'; printf '%s\\n' '--- media tools ---'; command -v ffmpeg || true; command -v ffprobe || true; python - <<'PY'
try:
 import cv2; print('cv2', cv2.__version__)
except Exception as e: print('no cv2', e)
try:
 import numpy; print('numpy', numpy.__version__)
except Exception as e: print('no numpy', e)
try:
 from PIL import Image; print('PIL ok')
except Exception as e: print('no PIL', e)
PY"

/bin/bash -c "python - <<'PY'
from PIL import Image,ImageDraw,ImageFont
im=Image.open('first_frame.png').resize((1024,576),Image.Resampling.NEAREST)
d=ImageDraw.Draw(im)
for x in range(0,257,10):
 X=x*4; d.line((X,0,X,576),fill=(255,0,0) if x%50==0 else (80,0,0),width=1)
 if x%20==0:d.text((X+1,1),str(x),fill=(255,100,100))
for y in range(0,145,10):
 Y=y*4; d.line((0,Y,1024,Y),fill=(255,0,0) if y%50==0 else (80,0,0),width=1)
 if y%20==0:d.text((1,Y+1),str(y),fill=(255,100,100))
im.save('.tmp/grid.png')
PY"

/bin/bash -c "python - <<'PY'
from PIL import Image,ImageDraw
im=Image.open('first_frame.png').crop((90,90,125,137)).resize((700,940),Image.Resampling.NEAREST)
d=ImageDraw.Draw(im)
for x in range(90,126):
 X=(x-90)*20; d.line((X,0,X,940),fill=(255,0,0),width=1)
 if x%5==0: d.text((X+2,2),str(x),fill=(255,100,100))
for y in range(90,138):
 Y=(y-90)*20; d.line((0,Y,700,Y),fill=(255,0,0),width=1)
 if y%5==0: d.text((2,Y+2),str(y),fill=(255,100,100))
im.save('.tmp/handle_grid.png')
PY"

